import {ribbonPolygons} from './plan-road-geometry.mjs';
import {pointInPolygon,parseMeters} from './buildings.mjs';
import {validPolygon,zoneColor} from './geo.mjs';
export const LAYERS={water:{name:'Вода',color:'#609fc0',description:'Водоёмы и водотоки OSM'},roads:{name:'Дорожная схема',color:'#c48b51',description:'Дороги; без ширины — осевая линия'},green:{name:'Озеленение',color:'#72a17a',description:'Зелёные территории и нанесённые деревья'},zones:{name:'Функциональное использование',color:'#ba9a71',description:'Использование OSM, не юридические зоны ПЗЗ'},labels:{name:'Подписи объектов',color:'#40566c',description:'Названия и адреса из OSM'},pedestrian:{name:'Пешеходная инфраструктура',color:'#a479b0',description:'Тропы, тротуары, велодорожки и переходы'}};
const pedestrian=p=>['footway','path','pedestrian','steps','cycleway'].includes(p.highway)||['footway','path','pedestrian','steps','cycleway'].includes(p['area:highway'])||p.highway==='crossing';
export function matchesLayer(f,key){const p=f.properties||{};if(!f.geometry||p.tainted)return false;switch(key){case'base':return true;case'water':return p.natural==='water'||!!p.water||['reservoir','basin'].includes(p.landuse)||['riverbank','river','stream','canal','drain','ditch'].includes(p.waterway);case'roads':return (!!p['area:highway']||!!p.highway&&!['construction','proposed','street_lamp','bus_stop','traffic_signals'].includes(p.highway))&&!pedestrian(p)&&f.geometry.type!=='Point';case'green':return ['tree','tree_row','wood','grassland','scrub'].includes(p.natural)||['forest','grass','meadow','recreation_ground'].includes(p.landuse)||p.leisure==='garden';case'zones':return !!zoneColor(p);case'labels':return !!(p.name||p['addr:housenumber']);case'pedestrian':return pedestrian(p);case'black':return !!p.building&&p.building!=='no'&&(!p['building:part']||p['building:part']==='no');default:return false;}}
export const filterLayer=(features,key)=>features.filter(f=>matchesLayer(f,key));
const polys=f=>f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[];
const lines=f=>f.geometry.type==='LineString'?[f.geometry.coordinates]:f.geometry.type==='MultiLineString'?f.geometry.coordinates:[];

const finiteCoordinates=a=>Array.isArray(a)&&a.length>0&&(typeof a[0]==='number'?a.length>=2&&a.every(Number.isFinite):a.every(finiteCoordinates));
export function labelAnchor(f,bounds){
 const inside=p=>p[0]>=bounds[1]&&p[0]<=bounds[3]&&p[1]>=bounds[0]&&p[1]<=bounds[2];
 if(f.geometry.type==='Point')return inside(f.geometry.coordinates)?f.geometry.coordinates:null;
 for(const poly of polys(f)){if(!validPolygon(poly))continue;const ring=poly[0],xs=ring.map(p=>p[0]),ys=ring.map(p=>p[1]),lo=[Math.max(bounds[1],Math.min(...xs)),Math.max(bounds[0],Math.min(...ys))],hi=[Math.min(bounds[3],Math.max(...xs)),Math.min(bounds[2],Math.max(...ys))];if(lo[0]>hi[0]||lo[1]>hi[1])continue;const center=lo.map((v,i)=>(v+hi[i])/2);if(pointInPolygon(center,poly))return center;for(let j=1;j<16;j++)for(let i=1;i<16;i++){const q=[lo[0]+(hi[0]-lo[0])*i/16,lo[1]+(hi[1]-lo[1])*j/16];if(pointInPolygon(q,poly))return q;}}
 let best=null,length=0;for(const line of lines(f))for(let i=1;i<line.length;i++){const a=line[i-1],b=line[i],d=[b[0]-a[0],b[1]-a[1]];let low=0,high=1;for(let k=0;k<2;k++){const min=bounds[k===0?1:0],max=bounds[k===0?3:2];if(!d[k]){if(a[k]<min||a[k]>max)high=-1;continue;}let x=(min-a[k])/d[k],y=(max-a[k])/d[k];if(x>y)[x,y]=[y,x];low=Math.max(low,x);high=Math.min(high,y);}if(high<low)continue;const l=Math.hypot(...d)*(high-low);if(l>length){length=l;best=a.map((v,k)=>v+d[k]*(low+high)/2);}}return best;
}

export function mergeRoadAreas(records,clip,onError=()=>{}){
 const out=records.filter(r=>!r.poly),groups=new Map();for(const r of records.filter(r=>r.poly)){const key=JSON.stringify([r.level,r.key,r.color,r.base]);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}
 for(const group of groups.values()){if(group.length<2||!clip?.union){out.push(...group);continue;}try{const merged=clip.union(...group.map(r=>r.poly));for(const poly of merged)out.push({...group[0],poly});}catch(error){onError(error);out.push(...group);}}
 return out;
}

export function outsideRoadAreas(line,areas){const out=[];for(let i=1;i<line.length;i++){const a=line[i-1],b=line[i],dx=b[0]-a[0],dy=b[1]-a[1],ts=[0,1];for(const poly of areas)for(const ring of poly)for(let j=1;j<ring.length;j++){const c=ring[j-1],d=ring[j],ex=d[0]-c[0],ey=d[1]-c[1],det=dx*ey-dy*ex;if(Math.abs(det)<1e-20)continue;const cx=c[0]-a[0],cy=c[1]-a[1],t=(cx*ey-cy*ex)/det,u=(cx*dy-cy*dx)/det;if(t>0&&t<1&&u>=0&&u<=1)ts.push(t);}ts.sort((x,y)=>x-y);for(let j=1;j<ts.length;j++){const lo=ts[j-1],hi=ts[j];if(hi-lo<1e-10)continue;const at=t=>[a[0]+dx*t,a[1]+dy*t];if(!areas.some(poly=>pointInPolygon(at((lo+hi)/2),poly)))out.push([at(lo),at(hi)]);}}return out;}

export function renderPlan(canvas,{features=[],bounds,side,mode='general',layers={},transparent=false,isolated=null,metadata=true,downloadedAt,estimatedWidths=true,clip=globalThis.polygonClipping,onGeometryError=error=>console.warn('Plan area union failed; original geometry retained',error)}={}){const c=canvas.getContext('2d'),W=canvas.width,H=canvas.height,m=50,size=Math.min(W-100,H-260),k=size/side;c.clearRect(0,0,W,H);if(!transparent){c.fillStyle='#fff';c.fillRect(0,0,W,H);}if(!bounds)return;const xy=p=>[m+(p[0]-bounds[1])/(bounds[3]-bounds[1])*size,m+size-(p[1]-bounds[0])/(bounds[2]-bounds[0])*size];c.save();c.beginPath();c.rect(m,m,size,size);c.clip();c.lineJoin='round';c.lineCap='round';
const roadQueue=[];
function flushRoads(){
 const trace=r=>{c.beginPath();for(const ring of r.poly||[r.line]){ring.forEach((v,i)=>{const q=xy(v);i?c.lineTo(...q):c.moveTo(...q)});if(r.poly)c.closePath();}};
 const interior=r=>r.base?'#fff':r.color==='#c48b51'?'#eedbc8':'#dbcde4';
 const levels=[...new Set(roadQueue.map(r=>r.level))].sort((a,b)=>a-b);
 for(const level of levels){
 const unxy=q=>[bounds[1]+(q[0]-m)/size*(bounds[3]-bounds[1]),bounds[0]+(m+size-q[1])/size*(bounds[2]-bounds[0])];
 const surfaces=[];
 for(const r of roadQueue.filter(r=>r.level===level)){if(r.poly||r.thin||!clip?.union){surfaces.push(r);continue;}
 for(const poly of ribbonPolygons(r.line.map(xy),r.width,[m,m,m+size,m+size]))surfaces.push({...r,line:undefined,poly:poly.map(ring=>ring.map(unxy))});}
 const group=mergeRoadAreas(surfaces,clip,onGeometryError);
 for(const r of group){trace(r);c.globalAlpha=1;c.strokeStyle=r.color;
 if(r.poly){c.fillStyle=interior(r);c.fill('evenodd');c.lineWidth=2;c.stroke();}
 else{c.lineWidth=r.thin?1.2:r.width+2;c.stroke();}
 }
 for(const r of group.filter(r=>!r.poly&&!r.thin)){trace(r);c.lineWidth=r.width;c.strokeStyle=interior(r);c.stroke();}
 }roadQueue.length=0;c.globalAlpha=1;
}


function draw(f,key,color,base=false){const p=f.properties||{};c.strokeStyle=color;c.fillStyle=color;c.lineWidth=base?1.2:2;for(const poly of polys(f)){if(!validPolygon(poly))continue;if(key==='roads'||key==='pedestrian'){const explicit=p.layer===undefined?NaN:Number(p.layer),level=Number.isFinite(explicit)?explicit:p.bridge&&p.bridge!=='no'?1:p.tunnel&&p.tunnel!=='no'?-1:0;roadQueue.push({poly,key,color,base,level});continue;}c.beginPath();for(const ring of poly){ring.forEach((v,i)=>{const q=xy(v);i?c.lineTo(...q):c.moveTo(...q)});c.closePath();}if(key==='black'){c.fillStyle=base?'#fff':'#15191c';c.fill('evenodd');}else{c.globalAlpha=base?.035:.25;c.fill('evenodd');c.globalAlpha=1;}c.stroke();}for(const line of lines(f)){c.beginPath();line.forEach((v,i)=>{const q=xy(v);i?c.lineTo(...q):c.moveTo(...q)});if(key==='roads'||key==='pedestrian'){const w=parseMeters(p.width),width=(w>0&&w<100?w:pedestrian(p)?2:6)*k;const explicit=Number(p.layer),level=Number.isFinite(explicit)?explicit:p.bridge&&p.bridge!=='no'?1:p.tunnel&&p.tunnel!=='no'?-1:0;roadQueue.push({line,key,width,color,base,level,thin:!(w>0&&w<100)&&!estimatedWidths});}else c.stroke();}if(f.geometry.type==='Point'){const q=xy(f.geometry.coordinates);c.beginPath();c.arc(...q,key==='green'?Math.max(3,1.5*k):3,0,Math.PI*2);c.stroke();}}
const safe=features.filter(f=>f.geometry&&!f.properties?.tainted&&finiteCoordinates(f.geometry.coordinates)).sort((a,b)=>JSON.stringify(a.geometry).localeCompare(JSON.stringify(b.geometry)));if(!isolated||isolated==='base'||isolated==='black'){if(mode==='black'||isolated==='black')filterLayer(safe,'black').forEach(f=>draw(f,'black','#15191c'));else{for(const key of ['green','water','roads','pedestrian'])filterLayer(safe,key).forEach(f=>draw(f,key,'#60666a',true));flushRoads();filterLayer(safe,'black').forEach(f=>draw(f,'black','#171c20',true));}}
const active=isolated?(['base','black'].includes(isolated)?[]:[isolated]):mode==='black'?[]:['zones','green','water','roads','pedestrian','black','labels'].filter(key=>layers[key]);for(const key of active){if(key==='labels')continue;if(!['roads','pedestrian'].includes(key))flushRoads();filterLayer(safe,key).forEach(f=>draw(f,key,key==='zones'?zoneColor(f.properties):LAYERS[key]?.color||'#15191c'));}
flushRoads();
if(active.includes('labels')){const occupied=[];c.font='16px Arial';c.fillStyle=LAYERS.labels.color;for(const f of filterLayer(safe,'labels')){const p=labelAnchor(f,bounds);if(!p)continue;const [x,y]=xy(p),text=String(f.properties.name||f.properties['addr:housenumber']).slice(0,65),w=c.measureText(text).width,box=[x,y-16,x+w,y+3];if(x<m||x+w>m+size||y<m+16||y>m+size||occupied.some(a=>box[0]<a[2]&&box[2]>a[0]&&box[1]<a[3]&&box[3]>a[1]))continue;occupied.push(box);c.fillText(text,x,y);}}
c.restore();if(metadata){c.fillStyle='#17232c';c.font='bold 25px Arial';c.fillText(isolated?(isolated==='base'?'Генеральный план':LAYERS[isolated]?.name||'Шварцплан'):mode==='black'?'Шварцплан':'Генеральный план · схема OSM',m,m+size+45);c.font='18px Arial';c.fillText('N ↑',m+size-45,35);c.fillRect(m,25,size/5,3);c.fillText(Math.round(side/5)+' м',m+size/5+15,35);c.fillText('© OpenStreetMap contributors · ODbL · '+String(downloadedAt||new Date().toISOString()).slice(0,10),m,m+size+80);const names=active.map(x=>LAYERS[x]?.name||(x==='black'?'Шварцплан':x));c.font='15px Arial';c.fillText('Слои: '+(names.slice(0,3).join(' · ')||'чёрно-белая основа'),m,m+size+110);if(names.length>3)c.fillText(names.slice(3).join(' · '),m,m+size+132);c.font='15px Arial';c.fillText('Схема по открытым данным, не геодезическая съёмка. Ширина дорог и символы деревьев могут быть условными.',m,m+size+158);c.fillText('Функциональное использование не является юридическим зонированием.',m,m+size+180);c.fillText('Центр: '+((bounds[0]+bounds[2])/2).toFixed(6)+', '+((bounds[1]+bounds[3])/2).toFixed(6),m,m+size+202);}}

export const layerDefs=[{key:"base",name:"Генеральный план",description:"Чёрно-белая основа",color:"#20262b"},{key:"black",name:"Шварцплан",description:"Пятна застройки",color:"#15191c"},...Object.entries(LAYERS).map(([key,v])=>({key,...v}))];